// -------------------------------------------
// Checks if a point is inside a circle
// -------------------------------------------
bool isInCircle(vec2 point, vec2 circleCenter, float circleRadius) {
    // Checks if the given point is within the circle defined by circleCenter and circleRadius
    return length(point - circleCenter) < circleRadius;
}

// -------------------------------------------
// Planet struct to store orbital parameters
// -------------------------------------------
struct Planet {
    float startPhase; // Initial angle offset
    float distance;   // Orbital radius from the sun
    float radius;     // Visual size
    vec3  color;      // Planet color
    vec2  position;   // Current planet position
    float alpha;      // Transparency of planet
};

// -------------------------------------------
// Compute angular velocity from distance,
// following a rough Kepler's 3rd law approach:
//   T^2 ~ R^3  =>  w = 1 / sqrt(R^3)
// -------------------------------------------
float getAngularVelocity(float orbitalRadius) {
    return 1.0 / sqrt(orbitalRadius * orbitalRadius * orbitalRadius);
}

// -------------------------------------------
// Compute planet’s position in 2D orbit
// Given a planet definition and time,
// returns (x, y) position
// -------------------------------------------
vec2 getPlanetPosition(Planet planet, float time) {
    float angularVelocity = getAngularVelocity(planet.distance);
    float angle = angularVelocity * time + planet.startPhase;
    return planet.distance * vec2(cos(angle), sin(angle));
}

// -------------------------------------------
// Finds the intersection point of two lines
// -------------------------------------------
vec2 lineIntersection(vec2 startPoint1, vec2 direction1, vec2 startPoint2, vec2 direction2) {
    // Solves for the intersection point of two lines defined by startPoint and direction vectors
    mat2 matrix = mat2(direction1, -direction2);
    vec2 diff = startPoint2 - startPoint1;
    vec2 t = inverse(matrix) * diff; // Solves for t1 and t2
    return startPoint1 + t.x * direction1; // Intersection point
}

// -------------------------------------------
// Computes the signed distance of the intersection
// -------------------------------------------
float lineIntersectionSignedDistance(vec2 startPoint1, vec2 direction1, vec2 startPoint2, vec2 direction2) {
    // Finds the signed distance of the intersection point from startPoint2
    vec2 intersectionPoint = lineIntersection(startPoint1, direction1, startPoint2, direction2);
    float distance = length(intersectionPoint - startPoint2);
    float signValue = sign(dot(intersectionPoint - startPoint2, direction2));

    if (dot(direction1, normalize(intersectionPoint - startPoint1)) < 0.0) {
        signValue *= -1.0;
    }

    return distance * signValue;
}

// -------------------------------------------
// Calculates tangent directions from a point to a circle
// -------------------------------------------
vec4 pointToCircleTangents(vec2 circleCenter, float radius, vec2 startPoint) {
    // Calculates the tangent directions from a given point to a circle
    vec2 toPoint = startPoint - circleCenter;
    float distSquared = dot(toPoint, toPoint);
    float dist = sqrt(distSquared);
    float projectionFactor = sqrt(distSquared - radius * radius) / dist;
    vec2 perp = vec2(-toPoint.y, toPoint.x) / dist;

    vec2 tangent1 = -(projectionFactor * toPoint + radius * perp);
    vec2 tangent2 = -(projectionFactor * toPoint - radius * perp);

    return vec4(normalize(tangent1), normalize(tangent2));
}

// -------------------------------------------
// Determines the coverage of a segment by intersections
// -------------------------------------------
float segmentCoverage(float segmentHalfWidth, float intersection1, float intersection2) {
    // Determines the coverage of a segment by intersections
    float start = min(intersection1, intersection2);
    float end = max(intersection1, intersection2);

    float segmentStart = -segmentHalfWidth;
    float segmentEnd = segmentHalfWidth;

    float overlapStart = max(segmentStart, start);
    float overlapEnd = min(segmentEnd, end);

    float overlapLength = max(0.0, overlapEnd - overlapStart);
    float segmentLength = segmentEnd - segmentStart;

    return overlapLength / segmentLength;
}

// -------------------------------------------
// Checks if a point is behind a planet
// relative to the sun
// -------------------------------------------
bool isBehindPlanet(vec2 sunPosition, vec2 planetPosition, vec2 point) {
    // Determines if a point is in the shadow of a planet relative to the sun
    vec2 sunToPoint = point - sunPosition;
    vec2 sunToPlanet = planetPosition - sunPosition;
    float sunToPlanetLength = length(sunToPlanet);

    float shadowLength = dot(sunToPoint, sunToPlanet) / sunToPlanetLength;

    return shadowLength > sunToPlanetLength;
}

// Planets 0-2 (inclusive) are planets, others are asteroids.
// Lower this number if you want more FPS, but there will be less asteroids.
// Smallest number you should put here is 3.
#define NUM_PLANETS 20
const float M_PI = 3.14159265358979323846264338327950288;
Planet planets[NUM_PLANETS];

float randomState = 0.0; // Random state initialized for the LCG

// -------------------------------------------
// Linear Congruential Generator (LCG)
// -------------------------------------------
float generateRandom(float seed) {
    randomState += 1.0;
    return fract(sin(randomState + seed) * 43758.5453123 + randomState);
}

// -------------------------------------------
// Returns a random float between min and max
// -------------------------------------------
float randomBetween(float minValue, float maxValue) {
    float randomValue = generateRandom(0.0); // Generates a random value in [0, 1]
    return mix(minValue, maxValue, randomValue);
}

// -------------------------------------------
// Shadertoy main entry
// -------------------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize coordinates so that (-1,0) is left, (1,0) is right, etc.
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y / 0.8;

    // Time variable scaled for simulation
    float time = iTime * 0.01;

    Planet sun = Planet(0.0, 0.0, 0.06, vec3(1.0, 0.85, 0.5), vec2(0.0, 0.0), 1.0); // Define the sun
    if (isInCircle(uv, sun.position, sun.radius)) {
        fragColor = vec4(sun.color, 1.0);
        return;
    }

    // ---------------------------------------
    // 1) Initialize planets
    // ---------------------------------------
    planets[0] = Planet(
        0.1,               // Start phase
        0.15,              // Orbital distance
        0.02,              // Radius
        vec3(0.2, 0.5, 1.0), // Color
        vec2(0.0, 0.0),    // Initial position
        1.0                // Alpha
    );
    planets[1] = Planet(
        1.2,               // Start phase
        0.5,               // Orbital distance
        0.03,              // Radius
        vec3(0.2, 1.0, 0.5), // Color
        vec2(0.0, 0.0),    // Initial position
        1.0                // Alpha
    );
    planets[2] = Planet(
        2.8,               // Start phase
        0.65,              // Orbital distance
        0.035,             // Radius
        vec3(1.0, 0.3, 0.3), // Color
        vec2(0.0, 0.0),    // Initial position
        1.0                // Alpha
    );

    // Asteroids. Main source of slowdown.
    for (int i = 3; i < NUM_PLANETS; i++) {
        planets[i] = Planet(
            randomBetween(-M_PI, M_PI),  // Random start phase
            randomBetween(0.34, 0.36),   // Random orbital distance
            randomBetween(0.005, 0.01), // Random radius
            vec3(0.5, 0.1, 0.2),        // Color
            vec2(0.0, 0.0),             // Initial position
            randomBetween(0.05, 0.15)    // Random alpha
        );
    }

    // Update planet positions based on current time
    for (int i = 0; i < NUM_PLANETS; i++) {
        planets[i].position = getPlanetPosition(planets[i], time);
    }

    // ---------------------------------------
    // 2) Compute lighting effects
    // ---------------------------------------
    float sunPower = 1.0;
    vec2 dirToSun = normalize(sun.position - uv);
    vec2 sunNormal = vec2(-dirToSun.y, dirToSun.x);

    for (int i = 0; i < NUM_PLANETS; i++) {
        if (!isBehindPlanet(sun.position, planets[i].position, uv)) continue;

        vec4 tangents = pointToCircleTangents(planets[i].position, planets[i].radius, uv);
        vec2 tangent1 = tangents.xy;
        vec2 tangent2 = tangents.zw;

        float intersection1 = lineIntersectionSignedDistance(uv, tangent1, sun.position, sunNormal);
        float intersection2 = lineIntersectionSignedDistance(uv, tangent2, sun.position, sunNormal);

        float coverage = segmentCoverage(sun.radius, intersection1, intersection2);
        coverage *= planets[i].alpha;
        sunPower *= 1.0 - coverage;
    }

    float sunFalloff = (1.0 - pow(length(uv) - sun.radius, 0.3));
    vec3 fog = vec3(sunPower, sunPower, sunPower) * sun.color * sunFalloff;

    vec3 color = fog;

    // ---------------------------------------
    // 3) Render planets
    // ---------------------------------------
    for (int i = 0; i < NUM_PLANETS; i++) {
        if (isInCircle(uv, planets[i].position, planets[i].radius)) {
            vec2 surface = uv - planets[i].position;
            float distSquared = surface.x * surface.x + surface.y * surface.y;
            float z = sqrt(planets[i].radius * planets[i].radius - distSquared);
            vec3 surfacePoint = vec3(surface.x, surface.y, z);
            vec3 normal = normalize(surfacePoint);
            float angleFactor = max(dot(normal, vec3(dirToSun, 0)), 0.1);
            vec3 planetColor = planets[i].color * max(sunPower, 0.5) * angleFactor;
            color = planetColor;
        }
    }

    fragColor = vec4(color, 1.0);
}
